PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE anomalies (
	id INTEGER NOT NULL, 
	observation_id INTEGER, 
	run_id INTEGER, 
	route_id INTEGER NOT NULL, 
	route_code VARCHAR(8) NOT NULL, 
	booking_horizon INTEGER, 
	detected_at DATETIME NOT NULL, 
	rule VARCHAR(128) NOT NULL, 
	severity VARCHAR(16) NOT NULL, 
	description TEXT, 
	fare_observed NUMERIC(12, 2), 
	fare_expected_low NUMERIC(12, 2), 
	fare_expected_high NUMERIC(12, 2), 
	detail JSON NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	is_genuine BOOLEAN, 
	reviewed_by VARCHAR(100), 
	reviewed_at DATETIME, 
	notes TEXT, 
	source_type VARCHAR(16) NOT NULL, acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(observation_id) REFERENCES fare_observations (id) ON DELETE SET NULL, 
	FOREIGN KEY(run_id) REFERENCES collection_runs (id) ON DELETE SET NULL
);
CREATE TABLE collection_runs (
	id INTEGER NOT NULL, 
	run_id VARCHAR(64) NOT NULL, 
	mode VARCHAR(16) NOT NULL, 
	source_type VARCHAR(16) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	display_label VARCHAR(32) NOT NULL, 
	started_at DATETIME NOT NULL, 
	finished_at DATETIME NOT NULL, 
	duration_ms INTEGER NOT NULL, 
	collection_day DATE NOT NULL, 
	routes_requested INTEGER NOT NULL, 
	routes_with_data INTEGER NOT NULL, 
	horizons_requested JSON NOT NULL, 
	observations_collected INTEGER NOT NULL, 
	observations_accepted INTEGER NOT NULL, 
	observations_flagged INTEGER NOT NULL, 
	observations_excluded INTEGER NOT NULL, 
	duplicates_removed INTEGER NOT NULL, 
	error_message TEXT, 
	collector_version VARCHAR(32) NOT NULL, 
	attempts JSON NOT NULL, 
	skipped_sources JSON NOT NULL, 
	dedupe_summary JSON NOT NULL, 
	triggered_by VARCHAR(32) NOT NULL, acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (run_id)
);
CREATE TABLE fare_observations (
	id INTEGER NOT NULL, 
	run_id INTEGER NOT NULL, 
	route_id INTEGER NOT NULL, 
	origin_code VARCHAR(3) NOT NULL, 
	destination_code VARCHAR(3) NOT NULL, 
	departure_date DATE NOT NULL, 
	booking_horizon_days INTEGER NOT NULL, 
	airline_code VARCHAR(3) NOT NULL, 
	airline_name VARCHAR(100), 
	flight_number VARCHAR(16), 
	cabin_class VARCHAR(20) NOT NULL, 
	fare_family VARCHAR(64), 
	stops INTEGER NOT NULL, 
	is_refundable BOOLEAN, 
	baggage_kg INTEGER, 
	seats_available INTEGER, 
	fare_total NUMERIC(12, 2) NOT NULL, 
	fare_base NUMERIC(12, 2), 
	fare_taxes NUMERIC(12, 2), 
	currency VARCHAR(3) NOT NULL, 
	source_currency VARCHAR(3), 
	source_fare_total NUMERIC(12, 2), 
	source_offer_id VARCHAR(128), 
	source_type VARCHAR(16) NOT NULL, 
	source_name VARCHAR(64) NOT NULL, 
	collection_timestamp DATETIME NOT NULL, 
	collection_date DATE NOT NULL, 
	request_id VARCHAR(64) NOT NULL, 
	collector_version VARCHAR(32) NOT NULL, 
	source_url VARCHAR(500), 
	raw_payload_hash VARCHAR(64), 
	provenance_notes JSON NOT NULL, 
	product_key VARCHAR(300) NOT NULL, 
	product_key_hash VARCHAR(32) NOT NULL, 
	dedupe_fingerprint VARCHAR(32) NOT NULL, 
	is_valid BOOLEAN NOT NULL, 
	validation_action VARCHAR(16) NOT NULL, 
	validation_flags JSON NOT NULL, acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, dep_time VARCHAR(16), dep_time_band VARCHAR(20), fare_udf NUMERIC(12, 2), fare_convenience NUMERIC(12, 2), 
	PRIMARY KEY (id), 
	FOREIGN KEY(run_id) REFERENCES collection_runs (id) ON DELETE CASCADE
);
CREATE TABLE "horizon_indices" (
	id INTEGER NOT NULL, 
	route_id INTEGER NOT NULL, 
	booking_horizon INTEGER NOT NULL, 
	index_date DATE NOT NULL, 
	index_value FLOAT NOT NULL, 
	index_100 FLOAT NOT NULL, 
	matched_products INTEGER NOT NULL, 
	observation_count INTEGER NOT NULL, 
	geometric_mean_price NUMERIC(12, 2) NOT NULL, 
	base_geometric_mean_price NUMERIC(12, 2) NOT NULL, 
	base_period_start DATE NOT NULL, 
	base_period_end DATE NOT NULL, 
	new_products INTEGER NOT NULL, 
	disappeared_products INTEGER NOT NULL, 
	reappeared_products INTEGER NOT NULL, 
	base_products INTEGER NOT NULL, 
	current_products INTEGER NOT NULL, 
	match_rate FLOAT, 
	standard_error FLOAT, 
	confidence_interval_low FLOAT, 
	confidence_interval_high FLOAT, 
	uncertainty_basis TEXT, 
	source_type VARCHAR(16) NOT NULL, 
	methodology_version VARCHAR(32) NOT NULL, 
	computed_at DATETIME NOT NULL, 
	matched_product_keys JSON NOT NULL, 
	acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_horizon_index UNIQUE (route_id, booking_horizon, index_date, source_type, acquisition_method, methodology_version)
);
CREATE TABLE index_revisions (
	id INTEGER NOT NULL, 
	target_table VARCHAR(32) NOT NULL, 
	target_index_date DATE NOT NULL, 
	target_route_id INTEGER, 
	target_booking_horizon INTEGER, 
	previous_value FLOAT, 
	new_value FLOAT, 
	revision_type VARCHAR(32) NOT NULL, 
	reason TEXT NOT NULL, 
	previous_methodology_version VARCHAR(32), 
	new_methodology_version VARCHAR(32) NOT NULL, 
	triggered_by VARCHAR(64) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE "national_indices" (
	id INTEGER NOT NULL, 
	index_date DATE NOT NULL, 
	booking_horizon INTEGER, 
	index_value FLOAT NOT NULL, 
	routes_included INTEGER NOT NULL, 
	routes_in_basket INTEGER NOT NULL, 
	total_observations INTEGER NOT NULL, 
	total_matched_products INTEGER NOT NULL, 
	coverage_weight FLOAT NOT NULL, 
	renormalization_applied BOOLEAN NOT NULL, 
	is_publishable BOOLEAN NOT NULL, 
	suppression_reason TEXT, 
	mom_change_pct FLOAT, 
	mom_status VARCHAR(32) NOT NULL, 
	yoy_change_pct FLOAT, 
	yoy_status VARCHAR(32) NOT NULL, 
	standard_error FLOAT, 
	confidence_interval_low FLOAT, 
	confidence_interval_high FLOAT, 
	uncertainty_basis TEXT, 
	seasonal_adjustment VARCHAR(32) NOT NULL, 
	base_period_start DATE NOT NULL, 
	base_period_end DATE NOT NULL, 
	base_period_label VARCHAR(64) NOT NULL, 
	weight_basket_id VARCHAR(64) NOT NULL, 
	weight_basket_version VARCHAR(32) NOT NULL, 
	weighting_method VARCHAR(64) NOT NULL, 
	weighting_status VARCHAR(32) NOT NULL, 
	source_type VARCHAR(16) NOT NULL, 
	provenance_label VARCHAR(32) NOT NULL, 
	methodology_version VARCHAR(32) NOT NULL, 
	validation_rules_version VARCHAR(32) NOT NULL, 
	computed_at DATETIME NOT NULL, 
	contributing_run_ids JSON NOT NULL, 
	route_contributions JSON NOT NULL, 
	missing_routes JSON NOT NULL, 
	acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_national_index UNIQUE (index_date, booking_horizon, source_type, acquisition_method, methodology_version)
);
CREATE TABLE normalized_fares (
	id INTEGER NOT NULL, 
	observation_id INTEGER NOT NULL, 
	route_id INTEGER NOT NULL, 
	booking_horizon_days INTEGER NOT NULL, 
	collection_date DATE NOT NULL, 
	product_key VARCHAR(300) NOT NULL, 
	product_key_hash VARCHAR(32) NOT NULL, 
	fare_inr NUMERIC(12, 2) NOT NULL, 
	source_type VARCHAR(16) NOT NULL, 
	fx_rate_applied FLOAT, 
	normalizer_version VARCHAR(32) NOT NULL, 
	is_included_in_index BOOLEAN NOT NULL, 
	exclusion_reason VARCHAR(64), acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, dep_time_band VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(observation_id) REFERENCES fare_observations (id) ON DELETE CASCADE
);
CREATE TABLE request_budgets (
	id INTEGER NOT NULL, 
	source_id VARCHAR(64) NOT NULL, 
	period_type VARCHAR(16) NOT NULL, 
	limit_count INTEGER NOT NULL, 
	warning_threshold_pct FLOAT DEFAULT '80.0' NOT NULL, 
	reduced_basket_threshold_pct FLOAT DEFAULT '95.0' NOT NULL, 
	is_hard_stop BOOLEAN DEFAULT '1' NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_request_budget_source_period UNIQUE (source_id, period_type)
);
CREATE TABLE request_usages (
	id INTEGER NOT NULL, 
	source_id VARCHAR(64) NOT NULL, 
	period_type VARCHAR(16) NOT NULL, 
	period_key VARCHAR(32) NOT NULL, 
	request_count INTEGER DEFAULT '0' NOT NULL, 
	successful_requests INTEGER DEFAULT '0' NOT NULL, 
	failed_requests INTEGER DEFAULT '0' NOT NULL, 
	last_request_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_request_usage_period UNIQUE (source_id, period_type, period_key)
);
CREATE TABLE "route_indices" (
	id INTEGER NOT NULL, 
	route_id INTEGER NOT NULL, 
	index_date DATE NOT NULL, 
	index_value FLOAT NOT NULL, 
	index_100 FLOAT NOT NULL, 
	horizons_included JSON NOT NULL, 
	horizons_missing JSON NOT NULL, 
	applied_horizon_weights JSON NOT NULL, 
	horizon_weighting_method VARCHAR(32) NOT NULL, 
	horizon_weighting_status VARCHAR(32) NOT NULL, 
	horizon_policy_version VARCHAR(32) NOT NULL, 
	matched_products INTEGER NOT NULL, 
	observation_count INTEGER NOT NULL, 
	standard_error FLOAT, 
	confidence_interval_low FLOAT, 
	confidence_interval_high FLOAT, 
	uncertainty_basis TEXT, 
	base_period_start DATE NOT NULL, 
	base_period_end DATE NOT NULL, 
	is_publishable BOOLEAN NOT NULL, 
	suppression_reason TEXT, 
	source_type VARCHAR(16) NOT NULL, 
	methodology_version VARCHAR(32) NOT NULL, 
	computed_at DATETIME NOT NULL, 
	acquisition_method VARCHAR(32) DEFAULT 'WEB_SCRAPE' NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_route_index UNIQUE (route_id, index_date, source_type, acquisition_method, methodology_version)
);
CREATE TABLE route_weights (
	id INTEGER NOT NULL, 
	basket_id VARCHAR(64) NOT NULL, 
	basket_version VARCHAR(32) NOT NULL, 
	effective_from DATE NOT NULL, 
	route_id INTEGER NOT NULL, 
	origin_code VARCHAR(3) NOT NULL, 
	destination_code VARCHAR(3) NOT NULL, 
	origin_city VARCHAR(100), 
	destination_city VARCHAR(100), 
	monthly_pax INTEGER NOT NULL, 
	weight FLOAT NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	weighting_method VARCHAR(64) NOT NULL, 
	weighting_status VARCHAR(32) NOT NULL, 
	is_official_expenditure_weight BOOLEAN NOT NULL, 
	recorded_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_route_weight_version UNIQUE (basket_version, route_id)
);
CREATE TABLE sources (
	id INTEGER NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	display_name VARCHAR(200) NOT NULL, 
	source_type VARCHAR(16) NOT NULL, 
	is_enabled BOOLEAN NOT NULL, 
	disabled_reason TEXT, 
	requires_credentials BOOLEAN NOT NULL, 
	homepage VARCHAR(500), 
	terms_url VARCHAR(500), 
	robots_url VARCHAR(500), 
	compliance_note TEXT, 
	native_currency VARCHAR(3) NOT NULL, 
	first_seen_at DATETIME NOT NULL, 
	last_updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE validation_results (
	id INTEGER NOT NULL, 
	observation_id INTEGER NOT NULL, 
	run_id INTEGER NOT NULL, 
	action VARCHAR(16) NOT NULL, 
	is_valid BOOLEAN NOT NULL, 
	flags JSON NOT NULL, 
	anomaly_type VARCHAR(32), 
	severity VARCHAR(16), 
	detail JSON NOT NULL, 
	rules_version VARCHAR(32) NOT NULL, 
	thresholds JSON NOT NULL, 
	evaluated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(observation_id) REFERENCES fare_observations (id) ON DELETE CASCADE, 
	FOREIGN KEY(run_id) REFERENCES collection_runs (id) ON DELETE CASCADE
);
CREATE TABLE validator_state (
	id INTEGER NOT NULL, 
	state_key VARCHAR(64) NOT NULL, 
	payload JSON NOT NULL, 
	rules_version VARCHAR(32) NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (state_key)
);
CREATE INDEX ix_route_weights_effective ON route_weights (effective_from);
CREATE INDEX ix_collection_runs_day ON collection_runs (collection_day);
CREATE INDEX ix_collection_runs_started ON collection_runs (started_at);
CREATE INDEX ix_revision_target ON index_revisions (target_table, target_index_date);
CREATE INDEX ix_revision_created ON index_revisions (created_at);
CREATE INDEX ix_fare_obs_product ON fare_observations (product_key_hash);
CREATE INDEX ix_fare_obs_collection_date ON fare_observations (collection_date, is_valid);
CREATE INDEX ix_fare_obs_horizon ON fare_observations (route_id, booking_horizon_days, collection_date);
CREATE INDEX ix_fare_obs_source_type ON fare_observations (source_type);
CREATE INDEX ix_fare_obs_route_day ON fare_observations (route_id, collection_date);
CREATE INDEX ix_fare_obs_dedupe ON fare_observations (dedupe_fingerprint);
CREATE INDEX ix_norm_product ON normalized_fares (product_key_hash, collection_date);
CREATE INDEX ix_norm_route_horizon_day ON normalized_fares (route_id, booking_horizon_days, collection_date);
CREATE INDEX ix_validation_obs ON validation_results (observation_id);
CREATE INDEX ix_validation_action ON validation_results (action);
CREATE INDEX ix_anomaly_status ON anomalies (status);
CREATE INDEX ix_anomaly_route_date ON anomalies (route_id, detected_at);
CREATE INDEX ix_collection_runs_acq_method ON collection_runs (acquisition_method);
CREATE INDEX ix_fare_obs_acq_method ON fare_observations (acquisition_method);
CREATE INDEX ix_horizon_index_date ON horizon_indices (index_date);
CREATE INDEX ix_horizon_route ON horizon_indices (route_id, index_date);
CREATE INDEX ix_route_index_date ON route_indices (index_date);
CREATE INDEX ix_national_index_date ON national_indices (index_date);
CREATE INDEX ix_budget_source ON request_budgets (source_id);
CREATE INDEX ix_usage_source_key ON request_usages (source_id, period_key);
COMMIT;
